def card(c):
    hits=''.join(f'<li><span>{E(t)}</span><b>{v}</b></li>' for t,v in c['hit'])
    miss=''.join(f'<li><span>{E(t)}</span><b>{v}</b></li>' for t,v in c['miss'])
    why=''.join(f'<li>{E(w)}</li>' for w in c['why'])
    return f'''<article class="ch" id="{E(c['n'].lower().replace(' ','-').replace('.',''))}">
<header><h3><a href="{E(c['url'])}" target="_blank" rel="noopener">{E(c['n'])} ↗</a></h3><p class="meta">{E(c['niche'])} · {c['subs']} abone · tahmini {c['rev']}/ay</p></header>
<div class="cols"><div><h4 class="ok">Tutanlar</h4><ul class="v">{hits}</ul></div><div><h4 class="bad">Tutmayanlar</h4><ul class="v">{miss}</ul></div></div>
<h4>Neden</h4><ul class="why">{why}</ul></article>'''
tpl=open(sys.argv[1]).read()
body=tpl.replace('<!--COMMON-->',''.join(f'<div class="rule"><h3>{E(a)}</h3><p>{E(b)}</p></div>' for a,b in COMMON))
body=body.replace('<!--CALMA-->',f'<p class="verdict">{E(CALMA["verdict"])}</p><ul class="why">'+''.join(f'<li>{E(p)}</li>' for p in CALMA['points'])+'</ul>')
body=body.replace('<!--CHANNELS-->',''.join(card(c) for c in CH))
body=body.replace('<!--TOC-->',''.join(f'<a href="#{E(c["n"].lower().replace(" ","-").replace(".",""))}">{E(c["n"])}</a>' for c in CH))
open(sys.argv[2],'w').write(body); print('ok')
